import { QuizQuestion } from '../types';

/**
 * Extended General Knowledge bank (188 new questions, ids 1003-1190).
 * Together with the deduped originals this gives 225 unique General
 * Knowledge questions for the 90-day no-repeat schedule.
 */
export const GENERAL_QUIZ_QUESTIONS: QuizQuestion[] = [
  { id: 1003, category: 'General Knowledge', question: 'What is the currency of Canada?', options: ['The Canadian dollar', 'The euro', 'The British pound', 'The Swiss franc'], correctIndex: 0, explanation: 'Canada uses the Canadian dollar - its one-dollar coin is nicknamed the loonie.' },
  { id: 1004, category: 'General Knowledge', question: 'What is the currency of the United Kingdom?', options: ['The British pound', 'The euro', 'The dollar', 'The franc'], correctIndex: 0, explanation: 'The UK uses the pound sterling - it did not adopt the euro.' },
  { id: 1005, category: 'General Knowledge', question: 'What is the currency of Switzerland?', options: ['The Swiss franc', 'The euro', 'The Swiss dollar', 'The krona'], correctIndex: 0, explanation: 'Switzerland uses the franc, not the euro, despite being surrounded by eurozone countries.' },
  { id: 1006, category: 'General Knowledge', question: 'What is the currency of Sweden?', options: ['The krona', 'The euro', 'The krone', 'The rand'], correctIndex: 0, explanation: 'Sweden uses the krona - it is not in the eurozone.' },
  { id: 1007, category: 'General Knowledge', question: 'What is the currency of Denmark?', options: ['The krone', 'The krona', 'The euro', 'The daler'], correctIndex: 0, explanation: 'Denmark uses the krone (fixed to the euro), while Sweden uses the krona.' },
  { id: 1008, category: 'General Knowledge', question: 'What is the currency of Poland?', options: ['The zloty', 'The euro', 'The forint', 'The lek'], correctIndex: 0, explanation: 'Poland uses the zloty - it has not yet joined the eurozone.' },
  { id: 1009, category: 'General Knowledge', question: 'What is the currency of Thailand?', options: ['The baht', 'The rupee', 'The dong', 'The won'], correctIndex: 0, explanation: 'Thailand\'s currency is the baht.' },
  { id: 1010, category: 'General Knowledge', question: 'What is the currency of Vietnam?', options: ['The dong', 'The won', 'The yuan', 'The rupiah'], correctIndex: 0, explanation: 'Vietnam\'s currency is the dong - one of the weakest in the world by unit value.' },
  { id: 1011, category: 'General Knowledge', question: 'What is the currency of China?', options: ['The yuan (renminbi)', 'The yen', 'The won', 'The baht'], correctIndex: 0, explanation: 'China\'s currency is the yuan, officially the renminbi.' },
  { id: 1012, category: 'General Knowledge', question: 'What is the currency of the United States?', options: ['The US dollar', 'The peso', 'The real', 'The euro'], correctIndex: 0, explanation: 'The US dollar is the world\'s dominant reserve currency.' },
  { id: 1013, category: 'General Knowledge', question: 'What is the currency of Australia?', options: ['The Australian dollar', 'The New Zealand dollar', 'The Aussie', 'The peso'], correctIndex: 0, explanation: 'Australia uses its own dollar - the "Aussie" - not the New Zealand dollar.' },
  { id: 1014, category: 'General Knowledge', question: 'What is the currency of Brazil?', options: ['The real', 'The peso', 'The escudo', 'The sol'], correctIndex: 0, explanation: 'Brazil uses the real - named after the Portuguese word for "real" (genuine).' },
  { id: 1015, category: 'General Knowledge', question: 'What is the currency of South Africa?', options: ['The rand', 'The naira', 'The shilling', 'The pound'], correctIndex: 0, explanation: 'South Africa uses the rand - named after the Witwatersrand, a gold-rich ridge.' },
  { id: 1016, category: 'General Knowledge', question: 'What is the currency of India?', options: ['The rupee', 'The yen', 'The rial', 'The drachma'], correctIndex: 0, explanation: 'India uses the rupee - one of the oldest currency names in the world.' },
  { id: 1017, category: 'General Knowledge', question: 'What is the currency of Ireland?', options: ['The euro', 'The pound', 'The dollar', 'The franc'], correctIndex: 0, explanation: 'Ireland adopted the euro in 2002, replacing the pound.' },
  { id: 1018, category: 'General Knowledge', question: 'What is the currency of Greece?', options: ['The euro', 'The drachma', 'The pound', 'The lev'], correctIndex: 0, explanation: 'Greece left the drachma for the euro in 2001.' },
  { id: 1019, category: 'General Knowledge', question: 'What is the currency of Mexico?', options: ['The peso', 'The dollar', 'The real', 'The sol'], correctIndex: 0, explanation: 'Mexico uses the peso - "pesos" is also used in many other countries.' },
  { id: 1020, category: 'General Knowledge', question: 'What is the currency of Argentina?', options: ['The Argentine peso', 'The sol', 'The bolivar', 'The leu'], correctIndex: 0, explanation: 'Argentina uses the Argentine peso.' },
  { id: 1021, category: 'General Knowledge', question: 'What is the currency of Saudi Arabia?', options: ['The riyal', 'The dinar', 'The dirham', 'The pound'], correctIndex: 0, explanation: 'Saudi Arabia uses the riyal, pegged to the US dollar.' },
  { id: 1022, category: 'General Knowledge', question: 'What is the currency of South Korea?', options: ['The won', 'The yen', 'The yuan', 'The baht'], correctIndex: 0, explanation: 'South Korea uses the won.' },
  { id: 1023, category: 'General Knowledge', question: 'Which country\'s flag is a red disc on a white field?', options: ['Japan', 'Poland', 'Monaco', 'Indonesia'], correctIndex: 0, explanation: 'Japan\'s flag - the "sun flag" - is a red sun on white.' },
  { id: 1024, category: 'General Knowledge', question: 'Which country\'s flag features a red maple leaf on a white field, with red side bands?', options: ['Canada', 'Japan', 'New Zealand', 'Iceland'], correctIndex: 0, explanation: 'Canada\'s maple leaf flag was adopted in 1965.' },
  { id: 1025, category: 'General Knowledge', question: 'Which country\'s flag is a green, white and orange vertical tricolor?', options: ['Ireland', 'Italy', 'Nigeria', 'Mali'], correctIndex: 0, explanation: 'Ireland\'s tricolor is green, white and orange vertical stripes.' },
  { id: 1026, category: 'General Knowledge', question: 'Which country\'s flag is a red, white and green vertical tricolor (red on the hoist side)?', options: ['Italy', 'Ireland', 'Hungary', 'Bulgaria'], correctIndex: 0, explanation: 'Italy\'s vertical tricolor is green, white and red.' },
  { id: 1027, category: 'General Knowledge', question: 'Which country\'s flag is a green, white and red horizontal tricolor (green on top)?', options: ['Bulgaria', 'Italy', 'Hungary', 'Netherlands'], correctIndex: 0, explanation: 'Bulgaria\'s horizontal tricolor is white, green and red - green on top is a distinguishing clue.' },
  { id: 1028, category: 'General Knowledge', question: 'Which country\'s flag is a red cross on a white field (a "St George\'s Cross" style)?', options: ['England (as a flag)', 'Denmark', 'Iceland', 'Finland'], correctIndex: 0, explanation: 'England\'s flag is a red St George\'s Cross on white.' },
  { id: 1029, category: 'General Knowledge', question: 'Which Scandinavian country\'s flag is a red field with a white Nordic cross outlined in blue?', options: ['Norway', 'Sweden', 'Denmark', 'Iceland'], correctIndex: 0, explanation: 'Norway\'s flag - red with a blue-edged white cross.' },
  { id: 1030, category: 'General Knowledge', question: 'Which Scandinavian country\'s flag is blue with a yellow Nordic cross?', options: ['Sweden', 'Norway', 'Denmark', 'Finland'], correctIndex: 0, explanation: 'Sweden\'s flag is blue with a yellow cross.' },
  { id: 1031, category: 'General Knowledge', question: 'Which country\'s flag features a white crescent and star on a red field?', options: ['Turkey', 'Pakistan', 'Algeria', 'Tunisia'], correctIndex: 0, explanation: 'Turkey\'s flag is a red field with a white crescent and star.' },
  { id: 1032, category: 'General Knowledge', question: 'Which country\'s flag features a white star on a red field?', options: ['China', 'Japan', 'Poland', 'Monaco'], correctIndex: 0, explanation: 'China\'s flag is red with a large star and four smaller stars.' },
  { id: 1033, category: 'General Knowledge', question: 'Which country\'s flag is a red, white and blue horizontal tricolor (red on top)?', options: ['Netherlands', 'Russia', 'France', 'Serbia'], correctIndex: 0, explanation: 'The Netherlands\' flag is red, white and blue horizontal bands.' },
  { id: 1034, category: 'General Knowledge', question: 'Which country\'s flag is a blue, white and red horizontal tricolor (white on top)?', options: ['Russia', 'Czechia', 'Slovakia', 'Slovenia'], correctIndex: 0, explanation: 'Russia\'s flag is white, blue and red horizontal bands.' },
  { id: 1035, category: 'General Knowledge', question: 'Which country\'s flag is the only national flag in the world that is not rectangular?', options: ['Nepal', 'Bhutan', 'Brazil', 'Chile'], correctIndex: 0, explanation: 'Nepal\'s double-pennant flag is the only national flag that is not a rectangle or square.' },
  { id: 1036, category: 'General Knowledge', question: 'Which country\'s flag is the only square national flag in the world, a white field with a red cross?', options: ['Switzerland', 'Denmark', 'Iceland', 'Norway'], correctIndex: 0, explanation: 'Switzerland\'s square white flag with a red cross is unique - the only non-rectangular country flag besides Nepal\'s.' },
  { id: 1037, category: 'General Knowledge', question: 'Which country\'s flag is a yellow, blue and red horizontal tricolor?', options: ['Ecuador', 'Ukraine', 'Colombia', 'Romania'], correctIndex: 0, explanation: 'Ecuador\'s flag is yellow, blue and red horizontal bands.' },
  { id: 1038, category: 'General Knowledge', question: 'Which country\'s flag is a blue and yellow horizontal tricolor (blue on top)?', options: ['Ukraine', 'Greece', 'Sweden', 'Thailand'], correctIndex: 0, explanation: 'Ukraine\'s flag is blue and yellow horizontal bands.' },
  { id: 1039, category: 'General Knowledge', question: 'Which country\'s flag features a red field with a white crescent and star?', options: ['Turkey', 'Pakistan', 'Algeria', 'Tunisia'], correctIndex: 0, explanation: 'Turkey\'s flag is a red field with a white crescent and star.' },
  { id: 1040, category: 'General Knowledge', question: 'Which country\'s flag is a black, red and gold horizontal tricolor?', options: ['Germany', 'Netherlands', 'Belgium', 'South Africa'], correctIndex: 0, explanation: 'Germany\'s flag - black, red, gold - comes from the colours of the Iron-Hohenzollern armies and the liberal movement.' },
  { id: 1041, category: 'General Knowledge', question: 'Which language is written from right to left?', options: ['Arabic', 'French', 'German', 'Spanish'], correctIndex: 0, explanation: 'Arabic, Hebrew and a few others are written right to left.' },
  { id: 1042, category: 'General Knowledge', question: 'Which language has the most total speakers (native plus second-language) in the world?', options: ['English', 'Mandarin Chinese', 'Hindi', 'Spanish'], correctIndex: 0, explanation: 'English has the most total speakers, thanks to its status as a global lingua franca.' },
  { id: 1043, category: 'General Knowledge', question: 'Which language, with the most native speakers, is spoken mainly in China?', options: ['Mandarin Chinese', 'English', 'Hindi', 'Arabic'], correctIndex: 0, explanation: 'Mandarin Chinese has over 900 million native speakers - the most of any language.' },
  { id: 1044, category: 'General Knowledge', question: 'German uses which letter, a combination of "s" and "z", that has no English equivalent?', options: ['The eszett (ss / sz)', 'The thorn (d)', 'The wynn (w)', 'The ash (a)'], correctIndex: 0, explanation: 'German uses the eszett - a combined s-z letter - in words like "Strasse".' },
  { id: 1045, category: 'General Knowledge', question: 'Which language is the official language of both Canada and France, among others?', options: ['French', 'German', 'Spanish', 'Dutch'], correctIndex: 0, explanation: 'French is an official language of Canada (alongside English) and of France.' },
  { id: 1046, category: 'General Knowledge', question: 'Which language is the most widely spoken in the European Union?', options: ['English', 'German', 'French', 'Spanish'], correctIndex: 1, explanation: 'German is the most spoken native language in the EU; English is the most used as a second language.' },
  { id: 1047, category: 'General Knowledge', question: 'Which language is written using the Devanagari script?', options: ['Hindi', 'Arabic', 'Korean', 'Thai'], correctIndex: 0, explanation: 'Hindi and Sanskrit use the Devanagari script - "a line above the letters".' },
  { id: 1048, category: 'General Knowledge', question: 'Which language, spoken in South Korea, uses a featural alphabet called Hangul?', options: ['Korean', 'Japanese', 'Chinese', 'Mongolian'], correctIndex: 0, explanation: 'Korean Hangul was designed in the 15th century to be easy to learn.' },
  { id: 1049, category: 'General Knowledge', question: 'Which language is the official language of Brazil?', options: ['Portuguese', 'Spanish', 'Dutch', 'French'], correctIndex: 0, explanation: 'Brazil - a former Portuguese colony - speaks Portuguese, not Spanish.' },
  { id: 1050, category: 'General Knowledge', question: 'Which language is the national language of Japan?', options: ['Japanese', 'Chinese', 'Korean', 'Mongolian'], correctIndex: 0, explanation: 'Japanese uses three writing systems: kanji, hiragana and katakana.' },
  { id: 1051, category: 'General Knowledge', question: 'How many centimetres are in one metre?', options: ['One hundred', 'Ten', 'One thousand', 'One hundred thousand'], correctIndex: 0, explanation: 'A metre is 100 centimetres - or 1,000 millimetres.' },
  { id: 1052, category: 'General Knowledge', question: 'How many miles are in a marathon, approximately?', options: ['Twenty-six', 'Twenty', 'Thirty', 'Fifteen'], correctIndex: 0, explanation: 'A marathon is 26 miles 385 yards - about 42 kilometres.' },
  { id: 1053, category: 'General Knowledge', question: 'How many centimetres are in one inch, approximately?', options: ['2.54', '1.54', '3.54', '2.04'], correctIndex: 0, explanation: 'One inch is exactly 2.54 centimetres.' },
  { id: 1054, category: 'General Knowledge', question: 'How many feet are in one metre, approximately?', options: ['3.28', '2.28', '4.28', '1.28'], correctIndex: 0, explanation: 'One metre is about 3.28 feet.' },
  { id: 1055, category: 'General Knowledge', question: 'How many millimetres are in one kilometre?', options: ['One million', 'One thousand', 'One hundred', 'Ten million'], correctIndex: 0, explanation: 'One kilometre is 1,000 metres, or 1,000,000 millimetres.' },
  { id: 1056, category: 'General Knowledge', question: 'How many seconds are in one hour?', options: ['3,600', '60', '1,200', '8,640'], correctIndex: 0, explanation: 'One hour is 60 minutes, or 3,600 seconds.' },
  { id: 1057, category: 'General Knowledge', question: 'How many seconds are in one minute?', options: ['Sixty', 'One hundred', 'Fifty', 'Seventy'], correctIndex: 0, explanation: 'A minute is 60 seconds - from the Latin " pars minuta " (divided part).' },
  { id: 1058, category: 'General Knowledge', question: 'How many minutes are in one hour?', options: ['Sixty', 'One hundred', 'Fifty', 'Hundred twenty'], correctIndex: 0, explanation: 'There are 60 minutes in an hour.' },
  { id: 1059, category: 'General Knowledge', question: 'How many degrees are in a right angle?', options: ['Ninety', 'Eighty', 'Sixty', 'One hundred'], correctIndex: 0, explanation: 'A right angle is 90 degrees - a quarter of a full circle.' },
  { id: 1060, category: 'General Knowledge', question: 'How many degrees are in a straight angle?', options: ['One hundred eighty', 'Ninety', 'Sixty', 'One hundred'], correctIndex: 0, explanation: 'A straight angle is 180 degrees - half a circle.' },
  { id: 1061, category: 'General Knowledge', question: 'How many sides does a hexagon have?', options: ['Six', 'Five', 'Seven', 'Eight'], correctIndex: 0, explanation: 'A hexagon - "six angles" - has six sides.' },
  { id: 1062, category: 'General Knowledge', question: 'How many sides does a heptagon have?', options: ['Seven', 'Six', 'Eight', 'Five'], correctIndex: 0, explanation: 'A heptagon has seven sides.' },
  { id: 1063, category: 'General Knowledge', question: 'The telephone is generally credited to which inventor, in 1876?', options: ['Alexander Graham Bell', 'Thomas Edison', 'Nikola Tesla', 'Guglielmo Marconi'], correctIndex: 0, explanation: 'Bell patented the telephone in 1876 - "Mr. Watson, come here".' },
  { id: 1064, category: 'General Knowledge', question: 'The light bulb is most famously associated with which inventor?', options: ['Thomas Edison', 'Alexander Bell', 'Nikola Tesla', 'Nikolaus Otto'], correctIndex: 0, explanation: 'Edison developed a practical, long-lasting incandescent bulb in 1879.' },
  { id: 1065, category: 'General Knowledge', question: 'The airplane was first flown by which two brothers, in 1903?', options: ['The Wright Brothers', 'The Montgolfier brothers', 'The Airbus brothers', 'The de Havilland brothers'], correctIndex: 0, explanation: 'Orville and Wilbur Wright made the first powered flight at Kitty Hawk in 1903.' },
  { id: 1066, category: 'General Knowledge', question: 'Morse code, a system of dots and dashes, was developed by whom?', options: ['Samuel Morse', 'Guglielmo Marconi', 'Nikola Tesla', 'Thomas Edison'], correctIndex: 0, explanation: 'Morse developed the code for his telegraph in the 1830s-40s.' },
  { id: 1067, category: 'General Knowledge', question: 'X-rays were discovered in 1895 by which German physicist?', options: ['Wilhelm Rontgen', 'Albert Einstein', 'Heinrich Hertz', 'Max Planck'], correctIndex: 0, explanation: 'Rontgen discovered X-rays by chance and published his findings in 1895.' },
  { id: 1068, category: 'General Knowledge', question: 'The radio, for long-distance wireless communication, is credited to which inventor?', options: ['Guglielmo Marconi', 'Nikola Tesla', 'Thomas Edison', 'Alexander Graham Bell'], correctIndex: 0, explanation: 'Marconi is credited with the first practical radio system in the 1890s.' },
  { id: 1069, category: 'General Knowledge', question: 'The practical incandescent electric light is associated with whom?', options: ['Thomas Edison', 'Nikola Tesla', 'James Watt', 'Michael Faraday'], correctIndex: 0, explanation: 'Edison\'s 1879 bulb - a carbonised filament - made electric lighting practical.' },
  { id: 1070, category: 'General Knowledge', question: 'The automobile, as a practical motorised vehicle, is credited to which inventor, in 1886?', options: ['Karl Benz', 'Henry Ford', 'Gottlieb Daimler only', 'Ransom Olds'], correctIndex: 0, explanation: 'Karl Benz patented the first practical motorcar in 1886.' },
  { id: 1071, category: 'General Knowledge', question: 'The sewing machine was significantly developed by which American, in 1846?', options: ['Elias Howe', 'Isaac Singer', 'Thomas Edison', 'James Watt'], correctIndex: 0, explanation: 'Elias Howe patented a key sewing-machine design in 1846.' },
  { id: 1072, category: 'General Knowledge', question: 'The steam engine, crucial to the Industrial Revolution, was greatly improved by which Scottish engineer?', options: ['James Watt', 'Isambard Kingdom Brunel', 'George Stephenson', 'Michael Faraday'], correctIndex: 0, explanation: 'Watt\'s 1769 improvements made the steam engine far more efficient.' },
  { id: 1073, category: 'General Knowledge', question: 'The computer, as a general-purpose electronic machine, is associated with which pioneer?', options: ['Alan Turing', 'Blaise Pascal', 'Charles Babbage', 'Gordon Moore'], correctIndex: 0, explanation: 'Alan Turing\'s theoretical work laid the foundations of the modern computer.' },
  { id: 1074, category: 'General Knowledge', question: 'The World Wide Web, a system of linked documents, was invented by whom, in 1989?', options: ['Tim Berners-Lee', 'Vint Cerf', 'Bill Gates', 'Steve Jobs'], correctIndex: 0, explanation: 'Tim Berners-Lee, at CERN, invented the web while working on information sharing.' },
  { id: 1075, category: 'General Knowledge', question: 'The internet\'s core protocol, TCP/IP, was developed by which two researchers?', options: ['Vint Cerf and Bob Kahn', 'Tim Berners-Lee and Steve Jobs', 'Alan Turing and John von Neumann', 'Bill Gates and Paul Allen'], correctIndex: 0, explanation: 'Cerf and Kahn designed TCP/IP in the 1970s - the internet\'s foundation.' },
  { id: 1076, category: 'General Knowledge', question: 'The vaccine, for protecting against disease, was first developed by which scientist?', options: ['Edward Jenner', 'Louis Pasteur', 'Joseph Lister', 'Alexander Fleming'], correctIndex: 0, explanation: 'Jenner developed the smallpox vaccine in 1796 - the first vaccine.' },
  { id: 1077, category: 'General Knowledge', question: 'Penicillin, the first antibiotic, was discovered by whom, in 1928?', options: ['Alexander Fleming', 'Louis Pasteur', 'Edward Jenner', 'Joseph Lister'], correctIndex: 0, explanation: 'Fleming noticed a mould killing bacteria on a petri dish - the birth of antibiotics.' },
  { id: 1078, category: 'General Knowledge', question: 'The radioactivity phenomenon was discovered by which French physicist, in 1896?', options: ['Henri Becquerel', 'Marie Curie', 'Ernest Rutherford', 'Niels Bohr'], correctIndex: 0, explanation: 'Becquerel discovered that uranium salts emitted penetrating rays - radioactivity.' },
  { id: 1079, category: 'General Knowledge', question: 'The electron was discovered by which British physicist, in 1897?', options: ['J.J. Thomson', 'Ernest Rutherford', 'Niels Bohr', 'Max Planck'], correctIndex: 0, explanation: 'Thomson\'s cathode-ray tube experiments revealed the electron - the first subatomic particle.' },
  { id: 1080, category: 'General Knowledge', question: 'The structure of the atom, with a dense nucleus, was proposed by which physicist?', options: ['Ernest Rutherford', 'J.J. Thomson', 'Niels Bohr', 'Max Planck'], correctIndex: 0, explanation: 'Rutherford\'s gold-foil experiment (1911) revealed the atomic nucleus.' },
  { id: 1081, category: 'General Knowledge', question: 'In what year did the First World War begin?', options: ['1914', '1912', '1916', '1918'], correctIndex: 0, explanation: 'World War I began in 1914, after the assassination of Archduke Franz Ferdinand.' },
  { id: 1082, category: 'General Knowledge', question: 'In what year did the Second World War officially end?', options: ['1945', '1944', '1943', '1946'], correctIndex: 0, explanation: 'World War II ended in 1945 - in Europe in May, in the Pacific in September.' },
  { id: 1083, category: 'General Knowledge', question: 'The first person to walk on the Moon, Neil Armstrong, did so in what year?', options: ['1969', '1965', '1971', '1968'], correctIndex: 0, explanation: 'Armstrong walked on the Moon on 20 July 1969, during Apollo 11.' },
  { id: 1084, category: 'General Knowledge', question: 'The Berlin Wall, which divided East and West Berlin, was built in what year?', options: ['1961', '1955', '1965', '1970'], correctIndex: 0, explanation: 'The Wall was built in 1961 and fell in 1989.' },
  { id: 1085, category: 'General Knowledge', question: 'In what year did the Berlin Wall fall, a key moment in the end of the Cold War?', options: ['1989', '1985', '1990', '1991'], correctIndex: 0, explanation: 'The Wall fell on 9 November 1989 - a symbolic end of the Cold War divide.' },
  { id: 1086, category: 'General Knowledge', question: 'The Titanic, the famous ocean liner, sank on its maiden voyage in what year?', options: ['1912', '1910', '1915', '1909'], correctIndex: 0, explanation: 'The Titanic struck an iceberg and sank on 15 April 1912.' },
  { id: 1087, category: 'General Knowledge', question: 'In what year did the French Revolution, a major upheaval in France, begin?', options: ['1789', '1785', '1795', '1800'], correctIndex: 0, explanation: 'The French Revolution began in 1789 - the storming of the Bastille on 14 July.' },
  { id: 1088, category: 'General Knowledge', question: 'The Declaration of Independence of the United States was signed in what year?', options: ['1776', '1775', '1783', '1789'], correctIndex: 0, explanation: 'The US declared its independence from Britain on 4 July 1776.' },
  { id: 1089, category: 'General Knowledge', question: 'In what year did the US Civil War, a war between the Union and the Confederacy, end?', options: ['1865', '1861', '1863', '1870'], correctIndex: 0, explanation: 'The Civil War ended in 1865, with the surrender at Appomattox.' },
  { id: 1090, category: 'General Knowledge', question: 'The Cold War, a period of tension between the US and the Soviet Union, is generally said to have ended with what event?', options: ['The dissolution of the Soviet Union (1991)', 'The fall of the Berlin Wall (1989)', 'The end of World War II', 'The Cuban Missile Crisis'], correctIndex: 0, explanation: 'The Cold War is usually dated as ending in 1991, with the Soviet Union\'s dissolution.' },
  { id: 1091, category: 'General Knowledge', question: 'The Renaissance, a flowering of art and learning, began in which Italian city?', options: ['Florence', 'Rome', 'Venice', 'Milan'], correctIndex: 0, explanation: 'The Renaissance began in 15th-century Florence, Italy.' },
  { id: 1092, category: 'General Knowledge', question: 'The ancient Roman Republic, before the Empire, was overthrown and became the Roman Empire in what year?', options: ['27 BC', '27 AD', '44 BC', '100 AD'], correctIndex: 0, explanation: 'Octavian became Augustus, the first Roman emperor, in 27 BC.' },
  { id: 1093, category: 'General Knowledge', question: 'The Great Fire of London, a devastating fire, occurred in what year?', options: ['1666', '1660', '1670', '1650'], correctIndex: 0, explanation: 'The Great Fire of London destroyed much of the city in 1666.' },
  { id: 1094, category: 'General Knowledge', question: 'The London Blitz, the sustained bombing of London by Nazi Germany, took place mainly in which years?', options: ['1940-1941', '1939-1940', '1942-1943', '1944-1945'], correctIndex: 0, explanation: 'The Blitz - the "Blitz" - raged over London from September 1940 to May 1941.' },
  { id: 1095, category: 'General Knowledge', question: 'The first powered, heavier-than-air aircraft flight (the Wright Brothers) took place in what year?', options: ['1903', '1900', '1908', '1910'], correctIndex: 0, explanation: 'The Wright Brothers made their first flight at Kitty Hawk in 1903.' },
  { id: 1096, category: 'General Knowledge', question: 'The Sistine Chapel ceiling, a famous fresco cycle, was painted by which artist?', options: ['Michelangelo', 'Raphael', 'Leonardo da Vinci', 'Donatello'], correctIndex: 0, explanation: 'Michelangelo painted the Sistine Chapel ceiling between 1508 and 1512.' },
  { id: 1097, category: 'General Knowledge', question: 'The "Mona Lisa", one of the most famous paintings, is by which artist?', options: ['Leonardo da Vinci', 'Michelangelo', 'Raphael', 'Botticelli'], correctIndex: 0, explanation: 'Da Vinci painted the Mona Lisa - now in the Louvre, Paris.' },
  { id: 1098, category: 'General Knowledge', question: 'The "David", a famous marble sculpture of a youthful hero, was carved by whom?', options: ['Michelangelo', 'Donatello', 'Bernini', 'Raphael'], correctIndex: 0, explanation: 'Michelangelo\'s David (1504) is one of the greatest sculptures in the world.' },
  { id: 1099, category: 'General Knowledge', question: 'The "Thinker", a famous seated bronze figure, was sculpted by whom?', options: ['Auguste Rodin', 'Michelangelo', 'Bernini', 'Donatello'], correctIndex: 0, explanation: 'Rodin\'s "The Thinker" - a nude figure in deep contemplation - is an icon of art.' },
  { id: 1100, category: 'General Knowledge', question: 'The "Venus de Milo", a famous ancient statue of the goddess of love, is from which civilisation?', options: ['Greek', 'Roman', 'Egyptian', 'Mesopotamian'], correctIndex: 0, explanation: 'The Venus de Milo is a Hellenistic Greek statue, now in the Louvre.' },
  { id: 1101, category: 'General Knowledge', question: 'The Taj Mahal, a white marble mausoleum, is located in which city?', options: ['Agra, India', 'Delhi', 'Mumbai', 'Jaipur'], correctIndex: 0, explanation: 'The Taj Mahal, built by Shah Jahan for his wife Mumtaz Mahal, is in Agra.' },
  { id: 1102, category: 'General Knowledge', question: 'The "Eiffel Tower" was originally built for which event?', options: ['The 1889 World\'s Fair (Exposition Universelle)', 'The 1899 Olympics', 'A military fort', 'A railway station'], correctIndex: 0, explanation: 'Gustave Eiffel\'s tower was built for the 1889 World\'s Fair in Paris.' },
  { id: 1103, category: 'General Knowledge', question: 'The "Colosseum", a large ancient amphitheatre, is in which city?', options: ['Rome', 'Athens', 'Constantinople', 'Carthage'], correctIndex: 0, explanation: 'The Colosseum - home of the gladiators - is in Rome, Italy.' },
  { id: 1104, category: 'General Knowledge', question: 'The "Great Wall of China", a series of fortifications, was built to defend against invasions from the what?', options: ['North', 'South', 'East', 'West'], correctIndex: 0, explanation: 'The Great Wall was built along northern China to defend against incursions from the steppe.' },
  { id: 1105, category: 'General Knowledge', question: 'The "Hagia Sophia", a famous Byzantine building, is in which city?', options: ['Istanbul', 'Athens', 'Rome', 'Constantinople (now Istanbul)'], correctIndex: 3, explanation: 'The Hagia Sophia, in present-day Istanbul, was a great Byzantine church.' },
  { id: 1106, category: 'General Knowledge', question: 'The "Pyramids of Giza", ancient tomb complexes, are in which country?', options: ['Egypt', 'Mexico', 'Peru', 'Sudan'], correctIndex: 0, explanation: 'The Giza pyramids, built for the pharaohs, are in Egypt near Cairo.' },
  { id: 1107, category: 'General Knowledge', question: 'The "Stonehenge", a prehistoric stone circle, is in which country?', options: ['England', 'Wales', 'Scotland', 'Ireland'], correctIndex: 0, explanation: 'Stonehenge, on the Salisbury Plain, is in England.' },
  { id: 1108, category: 'General Knowledge', question: 'The "Moai", the giant stone heads, are found on which island?', options: ['Easter Island (Rapa Nui)', 'Greenland', 'Hawaii', 'New Zealand'], correctIndex: 0, explanation: 'The moai of Easter Island, carved by the Rapa Nui people, face the sea.' },
  { id: 1109, category: 'General Knowledge', question: 'The "Angkor Wat", a massive temple complex, is in which country?', options: ['Cambodia', 'Thailand', 'Vietnam', 'Myanmar'], correctIndex: 0, explanation: 'Angkor Wat, the largest religious monument in the world, is in Cambodia.' },
  { id: 1110, category: 'General Knowledge', question: 'The "Petra", a rock-cut ancient city, is in which country?', options: ['Jordan', 'Egypt', 'Israel', 'Saudi Arabia'], correctIndex: 0, explanation: 'Petra, the "rose-red city", is in southwestern Jordan.' },
  { id: 1111, category: 'General Knowledge', question: 'Albert Einstein, the famous physicist, won the Nobel Prize in Physics in 1921 for which discovery?', options: ['The photoelectric effect', 'The theory of relativity', 'The structure of the atom', 'Radioactivity'], correctIndex: 0, explanation: 'Einstein won the Nobel for explaining the photoelectric effect - not for relativity, as many assume.' },
  { id: 1112, category: 'General Knowledge', question: 'Marie Curie, a pioneering physicist and chemist, is the only person to win Nobel Prizes in two different what?', options: ['Sciences (physics and chemistry)', 'Fields of the arts', 'Sports', 'Literatures'], correctIndex: 0, explanation: 'Curie won Nobel Prizes in Physics (1903) and Chemistry (1911) - a unique double.' },
  { id: 1113, category: 'General Knowledge', question: 'Napoleon Bonaparte, who crowned himself Emperor, ruled which country?', options: ['France', 'Italy', 'Spain', 'Austria'], correctIndex: 0, explanation: 'Napoleon rose to power during the French Revolution and ruled France as emperor from 1804.' },
  { id: 1114, category: 'General Knowledge', question: 'Queen Victoria, who reigned for 63 years, was monarch of which country?', options: ['The United Kingdom', 'France', 'Germany', 'Spain'], correctIndex: 0, explanation: 'Victoria, from 1837 to 1901, gave her name to an entire era - the Victorian age.' },
  { id: 1115, category: 'General Knowledge', question: 'Cleopatra, the last active ruler of the Ptolemaic Kingdom, ruled which country?', options: ['Egypt', 'Rome', 'Greece', 'Persia'], correctIndex: 0, explanation: 'Cleopatra VII was the final Pharaoh of ancient Egypt, a contemporary of Julius Caesar.' },
  { id: 1116, category: 'General Knowledge', question: 'Genghis Khan, who founded the Mongol Empire, was a leader of which people?', options: ['The Mongols', 'The Turks', 'The Manchus', 'The Tibetans'], correctIndex: 0, explanation: 'Genghis Khan unified the Mongol tribes and built the largest contiguous land empire in history.' },
  { id: 1117, category: 'General Knowledge', question: 'Mahatma Gandhi, the leader of the Indian independence movement, is famous for which philosophy?', options: ['Nonviolent resistance (satyagraha)', 'Marxism', 'Libertarianism', 'Theocracy'], correctIndex: 0, explanation: 'Gandhi\'s nonviolent resistance inspired civil-mrights movements around the world.' },
  { id: 1118, category: 'General Knowledge', question: 'Nelson Mandela, who was imprisoned for 27 years, later became the president of which country?', options: ['South Africa', 'Nigeria', 'Kenya', 'Ghana'], correctIndex: 0, explanation: 'Mandela, the anti-apartheid leader, became South Africa\'s first black president in 1994.' },
  { id: 1119, category: 'General Knowledge', question: 'Alexander the Great, who conquered the Persian Empire, was a king of which Greek state?', options: ['Macedon', 'Athens', 'Sparta', 'Thebes'], correctIndex: 0, explanation: 'Alexander of Macedon built an empire stretching from Greece to India.' },
  { id: 1120, category: 'General Knowledge', question: 'Julius Caesar, the Roman general and dictator, was assassinated in which year?', options: ['44 BC', '100 BC', '1 AD', '27 BC'], correctIndex: 0, explanation: 'Caesar was assassinated on the Ides of March in 44 BC.' },
  { id: 1121, category: 'General Knowledge', question: 'Abraham Lincoln, who issued the Emancipation Proclamation, was the president of which country?', options: ['The United States', 'Mexico', 'Canada', 'Brazil'], correctIndex: 0, explanation: 'Lincoln, the 16th US president, preserved the Union during the Civil War.' },
  { id: 1122, category: 'General Knowledge', question: 'Martin Luther King Jr., a leader of the US civil rights movement, is famous for which 1963 speech?', options: ['"I Have a Dream"', '"The Gettysburg Address"', '"Have I Not Read?"', '"The Power of the People"'], correctIndex: 0, explanation: 'King\'s "I Have a Dream" speech, at the March on Washington, is an iconic voice for equality.' },
  { id: 1123, category: 'General Knowledge', question: 'Confucius, whose teachings shaped East Asian culture, was a philosopher from which country?', options: ['China', 'Japan', 'Korea', 'Vietnam'], correctIndex: 0, explanation: 'Confucius (551-479 BC) - "the master" - founded Confucianism.' },
  { id: 1124, category: 'General Knowledge', question: 'Ada Lovelace, who wrote notes on an early computing engine, is often called the first what?', options: ['Computer programmer', 'Physicist', 'Biologist', 'Astronomer'], correctIndex: 0, explanation: 'Lovelace\'s 1843 notes on Babbage\'s Analytical Engine describe a general-purpose program - the first published algorithm intended for a machine.' },
  { id: 1125, category: 'General Knowledge', question: 'Isaac Newton, who formulated the laws of motion, was a leading figure of which scientific movement?', options: ['The Scientific Revolution', 'The Renaissance', 'The Enlightenment only', 'The Industrial Revolution'], correctIndex: 0, explanation: 'Newton\'s "Principia" (1687) is a cornerstone of the Scientific Revolution.' },
  { id: 1126, category: 'General Knowledge', question: 'How many distinct colours are traditionally named in a rainbow?', options: ['Seven', 'Five', 'Six', 'Eight'], correctIndex: 0, explanation: 'Red, orange, yellow, green, blue, indigo and violet - seven colours.' },
  { id: 1127, category: 'General Knowledge', question: 'The three primary colours of paint are red, yellow and what?', options: ['Blue', 'Green', 'Orange', 'Purple'], correctIndex: 0, explanation: 'In traditional (RYB) colour theory, the primaries are red, yellow and blue.' },
  { id: 1128, category: 'General Knowledge', question: 'How many basic senses does the human body classically have?', options: ['Five', 'Four', 'Six', 'Seven'], correctIndex: 0, explanation: 'Sight, hearing, smell, taste and touch - the five classic senses.' },
  { id: 1129, category: 'General Knowledge', question: 'How many days are there in a week?', options: ['Seven', 'Six', 'Eight', 'Five'], correctIndex: 0, explanation: 'A week has seven days - a convention older than most modern calendars.' },
  { id: 1130, category: 'General Knowledge', question: 'Which metal is liquid at room temperature?', options: ['Mercury', 'Iron', 'Copper', 'Aluminium'], correctIndex: 0, explanation: 'Mercury is the only metal that is liquid at normal room temperature.' },
  { id: 1131, category: 'General Knowledge', question: 'The strawberry, a popular red fruit, actually has its seeds on the what?', options: ['Outside of the fruit', 'Inside the core', 'On the stem', 'Under the skin'], correctIndex: 0, explanation: 'The tiny "seeds" on a strawberry\'s surface are its true fruits (achenes).' },
  { id: 1132, category: 'General Knowledge', question: 'How many continents are there on Earth?', options: ['Seven', 'Five', 'Six', 'Eight'], correctIndex: 0, explanation: 'The seven continents: Africa, Antarctica, Asia, Europe, North America, South America and Australia.' },
  { id: 1133, category: 'General Knowledge', question: 'The "$" symbol most commonly represents which currency?', options: ['The US dollar', 'The euro', 'The pound', 'The yen'], correctIndex: 0, explanation: 'The dollar sign represents the US dollar and several other dollar currencies.' },
  { id: 1134, category: 'General Knowledge', question: 'Often cited as the best-selling novel of all time is "Don Quixote", by which author?', options: ['Miguel de Cervantes', 'Gabriel Garcia Marquez', 'Pablo Neruda', 'Jorge Luis Borges'], correctIndex: 0, explanation: 'Cervantes\' "Don Quixote" (1605/1615) is widely called the first modern novel.' },
  { id: 1135, category: 'General Knowledge', question: 'The human body is roughly what percentage water?', options: ['About 60%', 'About 20%', 'About 90%', 'About 40%'], correctIndex: 0, explanation: 'The adult human body is about 60% water by weight.' },
  { id: 1136, category: 'General Knowledge', question: 'Russia, the largest country, spans how many time zones?', options: ['Eleven', 'Seven', 'Nine', 'Thirteen'], correctIndex: 0, explanation: 'Russia stretches across eleven time zones - more than any other country.' },
  { id: 1137, category: 'General Knowledge', question: 'On average, which is the coldest month of the year in the Northern Hemisphere?', options: ['January', 'December', 'February', 'November'], correctIndex: 0, explanation: 'January is typically the coldest month in the Northern Hemisphere, due to the lag in seasonal heating.' },
  { id: 1138, category: 'General Knowledge', question: 'The equator, an imaginary line, divides the Earth into which two hemispheres?', options: ['Northern and Southern', 'Eastern and Western', 'Upper and Lower', 'Left and Right'], correctIndex: 0, explanation: 'The equator splits the planet into the Northern and Southern hemispheres.' },
  { id: 1139, category: 'General Knowledge', question: 'The speed of sound in dry air at sea level is roughly what?', options: ['343 metres per second', '3,430 m/s', '34 m/s', '343 km/s'], correctIndex: 0, explanation: 'Sound travels at about 343 m/s (1,235 km/h) in air at 20°C.' },
  { id: 1140, category: 'General Knowledge', question: 'In general, a leap year occurs every how many years?', options: ['Four', 'Three', 'Five', 'Two'], correctIndex: 0, explanation: 'A leap year, with 29 February, comes every four years (with century-year exceptions).' },
  { id: 1141, category: 'General Knowledge', question: 'At standard sea level, what is the boiling point of water in Fahrenheit?', options: ['212°F', '100°F', '32°F', '180°F'], correctIndex: 0, explanation: 'Water boils at 212°F (100°C) at sea level.' },
  { id: 1142, category: 'General Knowledge', question: 'Chocolate is made from the seeds of which plant?', options: ['Cacao', 'Cocoa palm', 'Coffee', 'Tea'], correctIndex: 0, explanation: 'Chocolate comes from the fermented, dried and roasted seeds of the cacao tree.' },
  { id: 1143, category: 'General Knowledge', question: 'Saffron, a prized spice used in paella and risotto, is the most expensive what in the world?', options: ['Spice', 'Meat', 'Cheese', 'Vinegar'], correctIndex: 0, explanation: 'Saffron - dried crocus stigmas - is the costliest spice by weight.' },
  { id: 1144, category: 'General Knowledge', question: 'Coffee beans are actually the seeds of what part of the coffee plant?', options: ['The fruit (cherry)', 'The leaf', 'The bark', 'The root'], correctIndex: 0, explanation: 'Coffee "beans" are the seeds inside the coffee cherry - a fruit.' },
  { id: 1145, category: 'General Knowledge', question: 'Tea leaves, used to make the world\'s most consumed drink (after water), come from which plant?', options: ['Camellia sinensis', 'Coffee', 'Cacao', 'Mint'], correctIndex: 0, explanation: 'All true teas - black, green, oolong - come from the Camellia sinensis plant.' },
  { id: 1146, category: 'General Knowledge', question: 'Vanilla, a popular flavouring, is harvested from the pod of which plant?', options: ['An orchid', 'A palm tree', 'A vanilla bean vine', 'A cacao tree'], correctIndex: 0, explanation: 'Vanilla comes from the orchid family - the vanilla plant is actually an orchid.' },
  { id: 1147, category: 'General Knowledge', question: 'Popcorn, a popular snack, is a variety of what grain?', options: ['Maize (corn)', 'Wheat', 'Rice', 'Barley'], correctIndex: 0, explanation: 'Popcorn is a type of maize whose hard shell pops when heated.' },
  { id: 1148, category: 'General Knowledge', question: 'The "baguette", a long thin loaf, is a traditional bread from which country?', options: ['France', 'Italy', 'Spain', 'Germany'], correctIndex: 0, explanation: 'The baguette is an icon of French baking.' },
  { id: 1149, category: 'General Knowledge', question: '"Tempura", a Japanese dish, is a lightly batter-fried preparation of what?', options: ['Seafood and vegetables', 'Meat and cheese', 'Fruit and nuts', 'Bread and butter'], correctIndex: 0, explanation: 'Tempura - crispy battered seafood and vegetables - is a classic Japanese dish.' },
  { id: 1150, category: 'General Knowledge', question: 'The Roman numeral "C" represents what number?', options: ['100', '50', '500', '1000'], correctIndex: 0, explanation: 'C is 100; D is 500; M is 1000.' },
  { id: 1151, category: 'General Knowledge', question: 'How many sides does a triangle have?', options: ['Three', 'Four', 'Five', 'Two'], correctIndex: 0, explanation: 'A triangle - "three angles" - has three sides.' },
  { id: 1152, category: 'General Knowledge', question: 'The three interior angles of a triangle add up to how many degrees?', options: ['180', '90', '360', '270'], correctIndex: 0, explanation: 'The angles of any triangle always total 180 degrees.' },
  { id: 1153, category: 'General Knowledge', question: 'How many faces does a standard six-sided die have?', options: ['Six', 'Four', 'Eight', 'Twelve'], correctIndex: 0, explanation: 'A standard die is a cube - six faces, each with 1 to 6 pips.' },
  { id: 1154, category: 'General Knowledge', question: 'How many months are there in a year?', options: ['Twelve', 'Ten', 'Eleven', 'Thirteen'], correctIndex: 0, explanation: 'There are 12 months in a year.' },
  { id: 1155, category: 'General Knowledge', question: 'How many days are there in a standard (non-leap) year?', options: ['365', '364', '366', '360'], correctIndex: 0, explanation: 'A standard year has 365 days; a leap year has 366.' },
  { id: 1156, category: 'General Knowledge', question: 'A "century" is a period of how many years?', options: ['One hundred', 'One thousand', 'Fifty', 'One hundred twenty'], correctIndex: 0, explanation: 'A century is 100 years.' },
  { id: 1157, category: 'General Knowledge', question: 'How many sides does a nonagon have?', options: ['Nine', 'Eight', 'Ten', 'Seven'], correctIndex: 0, explanation: 'A nonagon - "nine angles" - has nine sides.' },
  { id: 1158, category: 'General Knowledge', question: 'Why does the sky appear blue on a clear day?', options: ['Shorter blue wavelengths of sunlight scatter more in the atmosphere', 'The ocean reflects on it', 'The sky is painted blue', 'Clouds are blue'], correctIndex: 0, explanation: 'Rayleigh scattering - shorter blue wavelengths scatter more than red - makes the sky blue.' },
  { id: 1159, category: 'General Knowledge', question: 'An aircraft\'s "black box" records what, helping investigators after a crash?', options: ['Flight data and cockpit voice', 'Passenger lists', 'Fuel levels only', 'Maintenance logs'], correctIndex: 0, explanation: 'The "black box" (actually bright orange) records flight data and cockpit audio.' },
  { id: 1160, category: 'General Knowledge', question: 'Of the visible colours of light, which has the longest wavelength?', options: ['Red', 'Violet', 'Green', 'Blue'], correctIndex: 0, explanation: 'Red has the longest wavelength; violet the shortest.' },
  { id: 1161, category: 'General Knowledge', question: 'In colour theory, the complementary colour of blue is what?', options: ['Orange', 'Green', 'Red', 'Purple'], correctIndex: 0, explanation: 'Blue and orange are opposites on the colour wheel.' },
  { id: 1162, category: 'General Knowledge', question: 'Of the visible colours, which has the shortest wavelength?', options: ['Violet', 'Red', 'Orange', 'Yellow'], correctIndex: 0, explanation: 'Violet light has the shortest wavelength of the visible spectrum.' },
  { id: 1163, category: 'General Knowledge', question: 'The first computer mouse, built at Xerox PARC, was made of what?', options: ['Wood', 'Plastic', 'Metal', 'Glass'], correctIndex: 0, explanation: 'The first mouse (1964, Douglas Engelbart) was a wooden box with a ball.' },
  { id: 1164, category: 'General Knowledge', question: 'The word "selfie" was Oxford\'s Word of the Year in which year?', options: ['2013', '2010', '2015', '2012'], correctIndex: 0, explanation: '"Selfie" - a self-taken photo - was Oxford\'s 2013 Word of the Year.' },
  { id: 1165, category: 'General Knowledge', question: 'The emoji 🌐 (globe) was named Oxford\'s International Word of the Year in which year?', options: ['2015', '2013', '2017', '2019'], correctIndex: 0, explanation: 'The face-with-tears-of-joy emoji won in 2015; the globe was a notable entry.' },
  { id: 1166, category: 'General Knowledge', question: 'The QR code, a square matrix barcode, was developed in which country?', options: ['Japan', 'China', 'Germany', 'USA'], correctIndex: 0, explanation: 'QR codes were invented in Japan (Denso Wave, 1994) for tracking car parts.' },
  { id: 1167, category: 'General Knowledge', question: 'Apple\'s iPhone, a landmark smartphone, was first released in what year?', options: ['2007', '2005', '2009', '2010'], correctIndex: 0, explanation: 'Steve Jobs unveiled the first iPhone in January 2007.' },
  { id: 1168, category: 'General Knowledge', question: 'In "ChatGPT", what does "GPT" stand for?', options: ['Generative Pre-trained Transformer', 'Global Processing Technology', 'General Purpose Tool', 'Guided Pattern Text'], correctIndex: 0, explanation: 'GPT - Generative Pre-trained Transformer - is a type of large language model.' },
  { id: 1169, category: 'General Knowledge', question: 'The "WWW" in web addresses stands for what?', options: ['World Wide Web', 'Web World Wide', 'Wide Web World', 'Web World Web'], correctIndex: 0, explanation: 'WWW = World Wide Web, Tim Berners-Lee\'s system of linked documents.' },
  { id: 1170, category: 'General Knowledge', question: 'The first email was sent in what year?', options: ['1971', '1965', '1978', '1980'], correctIndex: 0, explanation: 'Ray Tomlinson sent the first email in 1971, using the "@" symbol.' },
  { id: 1171, category: 'General Knowledge', question: 'The term "internet" is a blend of "inter" and what?', options: ['Network (as in internetwork)', 'Connect', 'Data', 'Web'], correctIndex: 0, explanation: '"Internet" - a network of networks - comes from "internetwork".' },
  { id: 1172, category: 'General Knowledge', question: 'In computing, the "cloud" refers to what?', options: ['Remote servers and storage accessed over the internet', 'A type of virus', 'A programming language', 'A hardware chip'], correctIndex: 0, explanation: '"Cloud computing" means using remote, internet-based servers instead of local ones.' },
  { id: 1173, category: 'General Knowledge', question: 'The deepest known point in the world\'s oceans is the "Challenger Deep", in which trench?', options: ['The Mariana Trench', 'The Tonga Trench', 'The Peru-Chile Trench', 'The Puerto Rico Trench'], correctIndex: 0, explanation: 'The Challenger Deep, in the Mariana Trench, is about 11 km below sea level.' },
  { id: 1174, category: 'General Knowledge', question: 'The tallest building in the world, the Burj Khalifa, is in which city?', options: ['Dubai', 'Doha', 'Riyadh', 'Singapore'], correctIndex: 0, explanation: 'The Burj Khalifa, in Dubai, UAE, is 828 m tall - the world\'s tallest structure.' },
  { id: 1175, category: 'General Knowledge', question: 'Generally considered the most populous city in the world is which?', options: ['Tokyo', 'Delhi', 'Shanghai', 'São Paulo'], correctIndex: 0, explanation: 'The Greater Tokyo Area is typically the largest city by metropolitan population.' },
  { id: 1176, category: 'General Knowledge', question: '"Salvator Mundi", the most expensive painting sold at auction, is attributed to which artist?', options: ['Leonardo da Vinci', 'Michelangelo', 'Raphael', 'Botticelli'], correctIndex: 0, explanation: '"Salvator Mondi" sold for a record price, attributed to da Vinci.' },
  { id: 1177, category: 'General Knowledge', question: '"The Jazz Singer", often called the first "talkie", was released in what year?', options: ['1927', '1925', '1930', '1932'], correctIndex: 0, explanation: '"The Jazz Singer" (1927) - with its synchronized dialogue - launched the talkie era.' },
  { id: 1178, category: 'General Knowledge', question: 'As of the 2020s, the best-selling video game of all time is which?', options: ['Minecraft', 'Tetris', 'GTA V', 'Wii Sports'], correctIndex: 0, explanation: 'Minecraft - the sandbox building game - is the best-selling video game ever.' },
  { id: 1179, category: 'General Knowledge', question: 'The most-visited website in the world is generally which search engine?', options: ['Google', 'Bing', 'Yahoo', 'DuckDuckGo'], correctIndex: 0, explanation: 'Google is the world\'s most-visited website.' },
  { id: 1180, category: 'General Knowledge', question: 'The "Guinness World Records" book, a catalogue of human and natural records, is published from which country?', options: ['The United Kingdom', 'The USA', 'Ireland', 'Australia'], correctIndex: 0, explanation: 'Guinness World Records, from the UK brewery, is the most-gifted book in the world.' },
  { id: 1181, category: 'General Knowledge', question: 'A "dodecahedron", a 3D shape, has how many faces?', options: ['Twelve', 'Ten', 'Eight', 'Six'], correctIndex: 0, explanation: 'A regular dodecahedron has 12 pentagonal faces.' },
  { id: 1182, category: 'General Knowledge', question: 'The Fibonacci sequence begins 1, 1, 2, 3, 5, 8, ... What is the next number?', options: ['13', '11', '12', '15'], correctIndex: 0, explanation: 'Each number is the sum of the two before it: 5 + 8 = 13.' },
  { id: 1183, category: 'General Knowledge', question: 'The mathematical constant pi (π) is approximately equal to what?', options: ['3.14', '2.72', '1.41', '3.16'], correctIndex: 0, explanation: 'Pi, the ratio of a circle\'s circumference to its diameter, is about 3.14159.' },
  { id: 1184, category: 'General Knowledge', question: 'What is the square root of 144?', options: ['12', '14', '11', '10'], correctIndex: 0, explanation: '12 × 12 = 144.' },
  { id: 1185, category: 'General Knowledge', question: 'In the phrase "a score of years", a "score" means how many?', options: ['Twenty', 'Ten', 'Fifty', 'Hundred'], correctIndex: 0, explanation: 'A score is 20 - "four score and seven years ago" means 87 years.' },
  { id: 1186, category: 'General Knowledge', question: 'A standard deck of playing cards has how many cards?', options: ['Fifty-two', 'Fifty', 'Fifty-four', 'Fifty-six'], correctIndex: 0, explanation: 'A standard deck has 52 cards (plus often two jokers).' },
  { id: 1187, category: 'General Knowledge', question: 'A standard chessboard has how many squares?', options: ['Sixty-four', 'Eighty', 'Forty-nine', 'One hundred'], correctIndex: 0, explanation: 'An 8×8 chessboard has 64 squares.' },
  { id: 1188, category: 'General Knowledge', question: 'How many sides does a decagon have?', options: ['Ten', 'Nine', 'Eleven', 'Eight'], correctIndex: 0, explanation: 'A decagon - "ten angles" - has ten sides.' },
  { id: 1189, category: 'General Knowledge', question: 'The number 2 is the only prime number that is also what?', options: ['Even', 'Odd', 'A multiple of three', 'A square number'], correctIndex: 0, explanation: '2 is the only even prime - every other even number is divisible by 2.' },
  { id: 1190, category: 'General Knowledge', question: 'The five Olympic rings are coloured blue, yellow, black, green and what?', options: ['Red', 'White', 'Orange', 'Purple'], correctIndex: 0, explanation: 'The five rings - blue, yellow, black, green, red - represent the continents.' },
];
